import React, { useEffect, useMemo, useRef } from "react";
import {
  type AllPuzzlesState,
  type AllPuzzlesRound,
} from "../../client/all_puzzles_types";
import { ErratumIcon } from "../ErratumIcon";
import { type Style } from "./useFolderHeights";

const TITLE_HEIGHT = 48;
const MARGIN_HEIGHT = 12;

const FolderCornerDecoration = ({
  fill,
  strokeColor,
  className,
}: {
  fill?: string;
  strokeColor?: string;
  className: string;
}) => {
  return (
    <svg
      width="26"
      height="25"
      viewBox="0 0 26 25"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
    >
      <mask
        id="mask0_663_13"
        style={{ maskType: "alpha" }}
        maskUnits="userSpaceOnUse"
        x="0"
        y="0"
        width="26"
        height="25"
      >
        <rect width="26" height="25" fill="#E9B28B" />
      </mask>
      <g mask="url(#mask0_663_13)">
        <path
          d="M636 47L636 475C636 487.703 625.703 498 613 498L-183 498C-195.703 498 -206 487.702 -206 475L-206 -1.00005C-206 -13.7026 -195.703 -24.0001 -183 -24.0001L-22 -24C-9.29746 -24 0.999985 -13.7026 0.999999 -1.00004C0.999999 12.8071 12.1929 24 26 24L613 24C625.703 24 636 34.2975 636 47Z"
          className={cn(
            fill || "fill-[#D5B893]",
            strokeColor || "stroke-[#FFE100]",
          )}
          strokeWidth="2"
        />
      </g>
    </svg>
  );
};

function isMobile(): boolean {
  let check = false;
  // Regex from here https://stackoverflow.com/questions/11381673/detecting-a-mobile-browser.
  (function (a) {
    if (
      /(android|bb\d+|meego).+mobile|avantgo|bada\/|blackberry|blazer|compal|elaine|fennec|hiptop|iemobile|ip(hone|od)|iris|kindle|lge |maemo|midp|mmp|mobile.+firefox|netfront|opera m(ob|in)i|palm( os)?|phone|p(ixi|re)\/|plucker|pocket|psp|series(4|6)0|symbian|treo|up\.(browser|link)|vodafone|wap|windows ce|xda|xiino/i.test(
        a,
      ) ||
      /1207|6310|6590|3gso|4thp|50[1-6]i|770s|802s|a wa|abac|ac(er|oo|s-)|ai(ko|rn)|al(av|ca|co)|amoi|an(ex|ny|yw)|aptu|ar(ch|go)|as(te|us)|attw|au(di|-m|r |s )|avan|be(ck|ll|nq)|bi(lb|rd)|bl(ac|az)|br(e|v)w|bumb|bw-(n|u)|c55\/|capi|ccwa|cdm-|cell|chtm|cldc|cmd-|co(mp|nd)|craw|da(it|ll|ng)|dbte|dc-s|devi|dica|dmob|do(c|p)o|ds(12|-d)|el(49|ai)|em(l2|ul)|er(ic|k0)|esl8|ez([4-7]0|os|wa|ze)|fetc|fly(-|_)|g1 u|g560|gene|gf-5|g-mo|go(\.w|od)|gr(ad|un)|haie|hcit|hd-(m|p|t)|hei-|hi(pt|ta)|hp( i|ip)|hs-c|ht(c(-| |_|a|g|p|s|t)|tp)|hu(aw|tc)|i-(20|go|ma)|i230|iac( |-|\/)|ibro|idea|ig01|ikom|im1k|inno|ipaq|iris|ja(t|v)a|jbro|jemu|jigs|kddi|keji|kgt( |\/)|klon|kpt |kwc-|kyo(c|k)|le(no|xi)|lg( g|\/(k|l|u)|50|54|-[a-w])|libw|lynx|m1-w|m3ga|m50\/|ma(te|ui|xo)|mc(01|21|ca)|m-cr|me(rc|ri)|mi(o8|oa|ts)|mmef|mo(01|02|bi|de|do|t(-| |o|v)|zz)|mt(50|p1|v )|mwbp|mywa|n10[0-2]|n20[2-3]|n30(0|2)|n50(0|2|5)|n7(0(0|1)|10)|ne((c|m)-|on|tf|wf|wg|wt)|nok(6|i)|nzph|o2im|op(ti|wv)|oran|owg1|p800|pan(a|d|t)|pdxg|pg(13|-([1-8]|c))|phil|pire|pl(ay|uc)|pn-2|po(ck|rt|se)|prox|psio|pt-g|qa-a|qc(07|12|21|32|60|-[2-7]|i-)|qtek|r380|r600|raks|rim9|ro(ve|zo)|s55\/|sa(ge|ma|mm|ms|ny|va)|sc(01|h-|oo|p-)|sdk\/|se(c(-|0|1)|47|mc|nd|ri)|sgh-|shar|sie(-|m)|sk-0|sl(45|id)|sm(al|ar|b3|it|t5)|so(ft|ny)|sp(01|h-|v-|v )|sy(01|mb)|t2(18|50)|t6(00|10|18)|ta(gt|lk)|tcl-|tdg-|tel(i|m)|tim-|t-mo|to(pl|sh)|ts(70|m-|m3|m5)|tx-9|up(\.b|g1|si)|utst|v400|v750|veri|vi(rg|te)|vk(40|5[0-3]|-v)|vm40|voda|vulc|vx(52|53|60|61|70|80|81|83|85|98)|w3c(-| )|webc|whit|wi(g |nc|nw)|wmlb|wonu|x700|yas-|your|zeto|zte-/i.test(
        a.substring(0, 4),
      )
    )
      check = true;
  })(navigator.userAgent || navigator.vendor);
  return check;
}

type RoundFolderProps = {
  variant?: "overworld" | "default";
  round: AllPuzzlesRound;
  count: number;
  children: React.ReactNode;
  index: number;
  getStyle: () => Style;
  state: AllPuzzlesState;
  href?: string;
  className?: string;
};

export const RoundFolder = ({
  variant = "default",
  round,
  count,
  children,
  getStyle,
  href,
  className,
}: RoundFolderProps) => {
  const ref = useRef<HTMLDivElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const mobile = useMemo(() => isMobile(), []);

  useEffect(() => {
    const onScroll = () => {
      const style = getStyle();
      if (!ref.current || !contentRef.current) {
        return;
      }

      // We make this update in a slightly hacky way because it's too slow if React is in the loop.
      // Specifically, it looks like the height adjustment is lagging the actual scroll motion.
      ref.current.style.position = style.sticky ? "sticky" : "relative";
      ref.current.style.top = style.sticky ? "16px" : "";
      ref.current.style.marginTop = `${style.marginTop}px`;
      contentRef.current.style.height =
        style.height === "auto"
          ? "auto"
          : `${style.height - TITLE_HEIGHT - MARGIN_HEIGHT}px`;
    };

    if (!mobile) {
      onScroll();

      document.addEventListener("scroll", onScroll);

      return () => {
        document.removeEventListener("scroll", onScroll);
      };
    }
  }, [getStyle, mobile]);

  return (
    <div
      ref={ref}
      className={cn(
        "relative overflow-x-visible min-w-[600px]",
        variant === "overworld" ? "mx-6" : "",
        className,
      )}
    >
      {/* The z-index should be larger than the children's z-index. */}
      <div
        className={cn(
          "relative flex items-end z-10 w-fit h-12 -mb-0.5 text-[26px] pl-6 pr-5 mt-auto border-2 border-b-0 rounded-t-2xl",
          variant === "overworld"
            ? "bg-folder-yellow border-folder-border"
            : "bg-[#D5B893] border-[#FFE100]",
        )}
      >
        <div className="flex items-center gap-2">
          <span className="font-title text-secondary transform-gpu drop-shadow-[0_2px_1px_rgba(0,0,0,0.25)] select-none">
            {href ? (
              <a
                href={href}
                aria-label={`Go to ${round.title} page`}
                role="button"
                className="text-secondary hover:text-accent-blue hover:drop-shadow-[0_2px_4px_rgba(60,135,210,0.5)] select-text"
              >
                {round.title.toUpperCase()}
              </a>
            ) : (
              <span>{round.title.toUpperCase()}</span>
            )}{" "}
            ({count})
          </span>
          <ErratumIcon
            resource={{ type: "round", slug: round.slug }}
            iconClassName="h-6 w-6"
          />
        </div>
        <FolderCornerDecoration
          className="absolute left-full"
          fill={variant === "overworld" ? "fill-folder-yellow" : undefined}
          strokeColor={
            variant === "overworld" ? "stroke-folder-border" : undefined
          }
        />
      </div>
      <div
        className={cn(
          "relative rounded-b-2xl rounded-tr-2xl border-[#FFE100] border-2 pt-3 select-none",
          round.puzzles.length > 0
            ? "bg-[linear-gradient(#D5B893,rgba(255,242,149,0.66)_15%,rgba(153,148,115,0.66))]"
            : "bg-[linear-gradient(#D5B893,rgba(255,242,149,0.66),rgba(153,148,115,0.66))]",
          variant === "overworld" &&
            "bg-gradient-to-b from-folder-yellow to-folder-orange border-folder-border",
        )}
      >
        <div className="box-content w-full pr-9 overflow-hidden">
          <div
            className="h-full flex flex-col justify-end box-border select-text"
            ref={contentRef}
          >
            {children}
          </div>
        </div>
      </div>
    </div>
  );
};
